var l=[{title:`Επιλέξτε προσβάσιμη κίνηση`,text:`Το περπάτημα, η ποδηλασία, η κολύμβηση, οι καθισιές με στήριξη και οι ασκήσεις δύναμης σε μηχανήματα μπορούν να είναι άνετα σημεία εκκίνησης, ανάλογα με την ικανότητα και την προτίμησή σας. Για ορισμένους ανθρώπους, το τζόκινγκ και τα επαναλαμβανόμενα άλματα βάζουν μεγαλύτερη απαίτηση στις αρθρώσεις ή στην αναπνοή από τις επιλογές χαμηλής κρούσης. Το μέγεθος του σώματος από μόνο του δεν κάνει καμία από αυτές τις δραστηριότητες σωστή ή λανθασμένη.`},{title:`Ξεκινήστε με δόση που μπορείτε να κάνετε`,text:`Ένας σύντομος περίπατος ή μερικά σετ ασκήσεων δύναμης με στήριξη μπορεί να αρκούν για να χτίσετε τη συνήθεια. Προσθέστε χρόνο, απόσταση ή επαναλήψεις σταδιακά καθώς μεγαλώνουν η αυτοπεποίθηση και η ανοχή σας. Δώστε προσοχή στο πώς αισθάνεται η κίνηση και τι μπορείτε να κάνετε την επόμενη εβδομάδα, και όχι μόνο στη ζυγαριά.`},{title:`Κοιτάξτε περισσότερα αποτελέσματα`,text:`Η ευκολότερη ανάβαση σκαλιών, οι μεγαλύτεροι περίπατοι, οι περισσότερες επαναλήψεις και η καλύτερη αποκατάσταση μετράνε όλα ως πρόοδος. Οι αλλαγές στο σωματικό βάρος εξαρτώνται από πολλούς παράγοντες, συμπεριλαμβανομένων των διατροφικών συνηθειών, των φαρμάκων και των παθήσεων υγείας. Η φυσική σας κατάσταση μπορεί να βελτιωθεί χωρίς μεγάλη αλλαγή στο βάρος.`},{title:`Ξεκινήστε από εκεί που είστε`,text:`Ορισμένοι άνθρωποι έχουν ήδη αρκετή εμπειρία στην άσκηση, ενώ άλλοι έχουν λίγο εξοπλισμό ή ιδιωτικότητα. Προσαρμόστε τις ασκήσεις στην περίστασή σας. Η απώλεια βάρους δεν χρειάζεται να είναι ο στόχος σας.`},{title:`Χρήση του TrainUp`,text:`Στο Profile, ορίστε τον χώρο προπόνησής σας, αν επιτρέπονται τα άλματα, τυχόν περιορισμούς ανά περιοχή του σώματος και το επίπεδο φυσικής κατάστασής σας. Το πρόγραμμα επιλέγει μόνο ασκήσεις που ταιριάζουν σε αυτές τις ρυθμίσεις. Το TrainUp διδάσκει άσκηση και δεν δίνει διατροφικά προγράμματα ή ιατρική φροντίδα διαχείρισης βάρους, οπότε αν έχετε συμπτώματα ή σύνθετες παθήσεις υγείας, ζητήστε ατομική συμβουλή από γιατρό.`}];var i=[{label:`NHS: περπάτημα για την υγεία`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`},{label:`CDC: υγιές βάρος και δραστηριότητα`,url:`https://www.cdc.gov/healthy-weight-growth/losing-weight/`},{label:`Θέση του ACSM για το 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var h={sections:l,sources:i};export{h as default,l as sections,i as sources};